/** Explicit access to the host Node V8 isolate through public node:v8 APIs. */
import * as node from "node:v8";
import { Buffer } from "node:buffer";
import { unsupportedNodeApi } from "./errors/core.js";
import { nativeCall, Writer, Reader } from "./v8/host-serialization.js";
export { Writer, Reader };
export function cachedDataVersionTag() {
    return nativeCall(() => node.cachedDataVersionTag());
}
export function statistics(kind) {
    return nativeCall(() => {
        switch (kind) {
            case "heap":
                return JSON.stringify(node.getHeapStatistics());
            case "spaces":
                return JSON.stringify(node.getHeapSpaceStatistics());
            case "code":
                return JSON.stringify(node.getHeapCodeStatistics());
            case "cpp-brief":
                return JSON.stringify(node.getCppHeapStatistics("brief"));
            case "cpp-detailed":
                return JSON.stringify(node.getCppHeapStatistics("detailed"));
        }
    });
}
/** Node produces the native snapshot synchronously; bytes are copied across WIT. */
export function getHeapSnapshot(options) {
    return nativeCall(() => {
        const stream = node.getHeapSnapshot(options);
        const chunks = [];
        try {
            for (let chunk = stream.read(); chunk !== null; chunk = stream.read()) {
                if (!(chunk instanceof Uint8Array)) {
                    throw new TypeError("V8 snapshot stream returned a non-byte chunk");
                }
                chunks.push(chunk);
            }
            return Buffer.concat(chunks);
        }
        finally {
            stream.destroy();
        }
    });
}
export function writeHeapSnapshot(filename, options) {
    return nativeCall(() => node.writeHeapSnapshot(filename, options));
}
export function setFlagsFromString(flags) {
    nativeCall(() => node.setFlagsFromString(flags));
}
export function takeCoverage() {
    nativeCall(() => node.takeCoverage());
}
export function stopCoverage() {
    nativeCall(() => node.stopCoverage());
}
export function setHeapSnapshotNearHeapLimit(limit) {
    nativeCall(() => node.setHeapSnapshotNearHeapLimit(limit));
}
export function openWriter(defaults) {
    return nativeCall(() => new Writer(defaults));
}
export function openReader(data, defaults) {
    return nativeCall(() => new Reader(data, defaults));
}
export class Profile {
    #profile;
    constructor(cpu) {
        if (cpu) {
            if (typeof node.startCpuProfile !== "function") {
                throw unsupportedNodeApi("v8.startCpuProfile()", "The Node host does not provide this API");
            }
            this.#profile = node.startCpuProfile();
        }
        else {
            const profiler = new node.GCProfiler();
            profiler.start();
            this.#profile = profiler;
        }
    }
    stop() {
        return nativeCall(() => {
            const profile = this.#profile;
            this.#profile = undefined;
            const result = profile?.stop();
            return typeof result === "string" ? result : JSON.stringify(result);
        });
    }
    [Symbol.dispose]() {
        this.stop();
    }
}
export function startProfile(cpu) {
    return nativeCall(() => new Profile(cpu));
}
export function releaseWriter(writer) {
    writer[Symbol.dispose]();
}
export function releaseReader(reader) {
    reader[Symbol.dispose]();
}
export function releaseProfile(profile) {
    profile[Symbol.dispose]();
}
export default {
    cachedDataVersionTag,
    statistics,
    getHeapSnapshot,
    writeHeapSnapshot,
    setFlagsFromString,
    takeCoverage,
    stopCoverage,
    setHeapSnapshotNearHeapLimit,
    openWriter,
    openReader,
    startProfile,
    releaseWriter,
    releaseReader,
    releaseProfile,
};
